# PowerShell betiği: gelen klasöründeki medya dosyalarını tarihe göre arşivle

$sourceDir = "gelen"
$targetBaseDir = "arsiv"

# Medya dosyası uzantıları
$mediaExtensions = @(".jpg", ".jpeg", ".png", ".mp4", ".mov")

# Tarih içeren dosyaların kontrolü için regex deseni
$tarihRegex = "(20\d{6}|\d{4}-\d{2}-\d{2})"

# Medya dosyası olmayanlar hariç, klasördeki tüm dosyaları al
Get-ChildItem -Path $sourceDir -File | ForEach-Object {
    $fileName = $_.Name
    $filePath = $_.FullName

    # Dosyanın uzantısı medya mı?
    if ($mediaExtensions -contains $_.Extension.ToLower()) {
        # Tarih bilgisini dosya adından çıkar
        $match = [regex]::Match($fileName, $tarihRegex)

        if ($match.Success) {
            $dateStr = $match.Value

            # Tarih formatını yyyyMMdd veya yyyy-MM-dd olarak ayırt et
            try {
                if ($dateStr -match "^\d{4}-\d{2}-\d{2}$") {
                    # Format: YYYY-MM-DD
                    $year = $dateStr.Substring(0, 4)
                    $month = $dateStr.Substring(5, 2)
                } else {
                    # Format: YYYYMMDD
                    $year = $dateStr.Substring(0, 4)
                    $month = $dateStr.Substring(4, 2)
                }

                # Hedef klasör yolu
                $targetDir = "$targetBaseDir\$year\$month"
                if (!(Test-Path $targetDir)) {
                    New-Item -ItemType Directory -Path $targetDir -Force
                }

                # Dosyayı taşımak için hedef dosya yolu
                $targetFile = "$targetDir\$fileName"

                # Taşıma işlemi
                Move-Item -Path $filePath -Destination $targetFile
                Write-Host "Taşındı: $fileName -> $targetFile"
            } catch {
                Write-Warning "Tarih bilgisi çözümlenemiyor: $fileName"
            }
        } else {
            # Tarihi bulunamayan dosya, tarihsiz klasörüne taşınacak
            $targetDir = "$targetBaseDir\tarihsiz"
            if (!(Test-Path $targetDir)) {
                New-Item -ItemType Directory -Path $targetDir -Force
            }

            # Dosyayı taşımak için hedef dosya yolu
            $targetFile = "$targetDir\$fileName"

            Move-Item -Path $filePath -Destination $targetFile
            Write-Host "Taşındı (tarihsiz): $fileName -> $targetFile"
        }
    } else {
        # Medya olmayan dosya, yerinde kalacak
        Write-Host "Medya değil: $fileName"
    }
}

